// === Tab: mySketch ===
// By wufu
// https://openprocessing.org/user/261339

Particles = []
const ParticleNum = 150
const MinDist = 20
const Radius = 5

function setup() {
	createCanvas(500, 500)
	for (i = 0; i < ParticleNum; i++) {
		Velocity = createVector(0, 0)
		Particles[i] = new Particle(
			true,
			random(Radius, width-Radius),
			random(Radius, height-Radius),
			Particles,
			Velocity
		)
	}
}

function draw() {
	background(0)
	for (let particle of Particles) {
		particle.MoveStateChange()
		particle.EdgeCheck()
		particle.Move()
		particle.Display()
	}
}

class Particle {
	constructor(MoveCheck, CoordinateX, CoordinateY, ParticlesList, VelocityVector) {
		this.MoveCheckNum = 0
		this.MoveCheck = MoveCheck
		this.x = CoordinateX
		this.y = CoordinateY
		this.particles = ParticlesList
		this.v = VelocityVector
	}

	MoveStateCheck(other) {
		let d = dist(this.x, this.y, other.x, other.y)
		if (d < MinDist) {
			this.MoveCheckNum += 0.2 //determinate the difficulty of crystallization
		}
	}

	MoveStateChange() {
		this.MoveCheckNum = 0
		for (let other of this.particles) {
			if (this != other) {
				this.MoveStateCheck(other)
			}
		}
		if (this.MoveCheckNum >= 1) {
			this.MoveCheck = false
		}
	}

	EdgeCheck() {
		if (this.x + Radius >= width || this.x - Radius <= 0) {
			this.v.x *= -1
		}
		if (this.y + Radius >= height || this.y - Radius <= 0) {
			this.v.y *= -1
		}
	}

	Move() {
		if (this.MoveCheck) {
			this.x += this.v.x
			this.y += this.v.y
			this.v.limit(5)
			this.v.x += random(-0.2, 0.2)
			this.v.y += random(-0.2, 0.2)
		}
	}

	Display() {
		fill(255)
		ellipse(this.x, this.y, Radius*2)
	}
}

